"use client";

import { Bell, CircleAlert, X } from "lucide-react";
import { motion as m, useIsPresent, useReducedMotion } from "motion/react";
import type { ReactNode } from "react";
import { cn } from "@/lib/utils";

export type StackNotification = {
  id: string;
  title: string;
  description?: string;
  icon?: ReactNode;
  tone?: "default" | "error";
  duration?: number;
};

export function NotificationCard({ item, offset, layer, depth, position, motion, className, dismiss }: {
  item: StackNotification; offset: number; layer: number; depth: number; position: "top" | "bottom";
  motion: boolean; className?: string; dismiss: () => void;
}) {
  const present = useIsPresent();
  const reduced = useReducedMotion();
  const animate = motion && !reduced;
  const y = -offset;
  const scale = 1 - Math.min(depth, 4) * 0.05;
  return <m.li data-notification-id={item.id} aria-hidden={!present || undefined}
    className={cn("absolute inset-x-1 bottom-1 min-w-0 rounded-xl border border-border bg-[color-mix(in_srgb,var(--popover)_55%,var(--background))] px-3 py-3 text-popover-foreground shadow-sm", className)}
    style={{ zIndex: present ? layer : 0, pointerEvents: present ? undefined : "none",
      transformOrigin: position === "bottom" ? "center top" : "center bottom" }}
    initial={animate ? { y: y + (position === "top" ? -18 : 18), scale, opacity: 0 } : false}
    animate={{ y, scale, opacity: 1 }} exit={{ opacity: 0 }}
    transition={{ duration: animate ? 0.28 : 0, ease: [0.22, 0.68, 0.16, 1] }}>
    <div className="flex items-start gap-2.5">
      <span aria-hidden="true" className={cn("mt-1.5 shrink-0 text-primary [&>svg]:size-4", item.tone === "error" && "text-destructive")}>
        {item.icon ?? (item.tone === "error" ? <CircleAlert /> : <Bell />)}
      </span>
      <div className="min-w-0 flex-1 self-center">
        <p className="text-sm font-semibold leading-5 [overflow-wrap:anywhere]">{item.title}</p>
        {item.description && <p className="pt-1 text-xs leading-relaxed text-muted-foreground [overflow-wrap:anywhere]">{item.description}</p>}
      </div>
      <button type="button" aria-label={`Dismiss ${item.title}`} title="Dismiss notification"
        disabled={!present} onClick={dismiss} className="grid size-7 shrink-0 place-items-center rounded-md text-muted-foreground hover:bg-muted hover:text-foreground focus-visible:bg-muted focus-visible:outline focus-visible:outline-1">
        <X aria-hidden="true" className="size-3.5" />
      </button>
    </div>
  </m.li>;
}

"use client";

import { useLayoutEffect, useState, type RefObject } from "react";
import type { StackNotification } from "./notification-card";

// Use the layout height so an in-flight depth scale cannot feed back into the next offset.
export function useCardHeights(list: RefObject<HTMLOListElement | null>, items: readonly StackNotification[], count: number) {
  const [heights, setHeights] = useState<ReadonlyMap<string, number>>(() => new Map());
  useLayoutEffect(() => {
    if (!list.current) return;
    const cards = Array.from(list.current.querySelectorAll<HTMLElement>("li[data-notification-id]:not([aria-hidden=true])"));
    function measure() {
      const next = new Map(cards.map(card => {
        const css = getComputedStyle(card);
        const height = css.boxSizing === "border-box" ? parseFloat(css.height) : card.offsetHeight;
        return [card.dataset.notificationId!, height || card.offsetHeight];
      }));
      setHeights(previous => previous.size === next.size && [...next].every(([id, h]) => previous.get(id) === h) ? previous : next);
    }
    measure();
    if (typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(measure);
    cards.forEach(card => observer.observe(card));
    return () => observer.disconnect();
  }, [list, items, count]);
  return heights;
}

export function notificationLayout(items: readonly StackNotification[], heights: ReadonlyMap<string, number>,
  expanded: boolean, position: "top" | "bottom") {
  // Work from the front card toward the back. A tall card can protrude at the far edge,
  // but never beyond the near edge of the card in front of it.
  const newestFirst = position === "top" ? items : [...items].reverse();
  const offsets = new Map<string, number>();
  let extent = 0;
  for (const [depth, item] of newestFirst.entries()) {
    const height = heights.get(item.id) || 70;
    const offset = depth === 0 ? 0 : expanded ? extent + 8 : Math.max(0, extent + 12 - height);
    offsets.set(item.id, offset);
    extent = offset + height;
  }
  if (position === "top") {
    for (const item of items) {
      offsets.set(item.id, extent - offsets.get(item.id)! - (heights.get(item.id) || 70));
    }
  }
  return { height: extent, offsets };
}

"use client";

import { Bell, ChevronDown, ChevronUp } from "lucide-react";
import { AnimatePresence } from "motion/react";
import { useId, useRef, useState, type FocusEvent, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { NotificationCard, type StackNotification } from "./notification-card";
import { NotificationTimer } from "./notification-timer";
import { notificationLayout, useCardHeights } from "./notification-layout";

export type { StackNotification } from "./notification-card";

export type NotificationStackProps = {
  items: readonly StackNotification[];
  onDismiss: (id: string) => void;
  duration?: number;
  visible?: number;
  position?: "top" | "bottom";
  defaultExpanded?: boolean;
  motion?: boolean;
  className?: string;
  cardClassName?: string;
  emptyIcon?: ReactNode;
};

export function NotificationStack({ items, onDismiss, duration = 5000, visible = 3, position = "bottom",
  defaultExpanded = false, motion = true, className, cardClassName, emptyIcon }: NotificationStackProps) {
  const [showAll, setShowAll] = useState(defaultExpanded);
  const [hover, setHover] = useState(false);
  const [focus, setFocus] = useState(false);
  const [readingCards, setReadingCards] = useState(false);
  const region = useRef<HTMLElement>(null);
  const list = useRef<HTMLOListElement>(null);
  const listId = useId();
  const expanded = showAll || hover || readingCards;
  const limit = Math.max(1, Math.trunc(visible) || 1);
  const shown = showAll ? [...items] : items.slice(-limit);
  if (position === "top") shown.reverse();
  const heights = useCardHeights(list, items, shown.length);
  const layout = notificationLayout(shown, heights, expanded, position);

  function dismissCard(id: string, index: number) {
    const buttons = list.current?.querySelectorAll<HTMLButtonElement>("li:not([aria-hidden=true]) button");
    if (buttons?.[index]?.contains(document.activeElement)) {
      (buttons[index + 1] ?? buttons[index - 1] ?? region.current)?.focus();
    }
    onDismiss(id);
  }

  function left(event: FocusEvent<HTMLElement>) {
    return !event.currentTarget.contains(event.relatedTarget);
  }

  return <section ref={region} aria-label="Notifications" tabIndex={-1}
    className={cn("flex h-80 w-full min-w-0 flex-col justify-end text-foreground [overflow-anchor:none]", className)}
    onFocusCapture={() => setFocus(true)} onBlurCapture={event => { if (left(event)) setFocus(false); }}>
    {items.map(item => <NotificationTimer key={item.id} id={item.id} duration={item.duration ?? duration}
      paused={focus || hover} onDismiss={onDismiss} />)}
    {(["polite", "assertive"] as const).map(priority => <div key={priority} aria-live={priority}
      aria-relevant="additions" aria-atomic="false" className="sr-only">
      {items.filter(item => (item.tone === "error") === (priority === "assertive")).map(item =>
        <p key={item.id}>{item.title}{item.description && `. ${item.description}`}</p>)}
    </div>)}
    {items.length === 0 && <div className="grid justify-items-center gap-2 py-6 text-sm text-muted-foreground">
      <span aria-hidden="true" className="grid size-9 place-items-center rounded-full bg-muted">{emptyIcon ?? <Bell className="size-4" />}</span>
      All caught up.
    </div>}
    <div className={cn("relative min-h-0", items.length > 0 && "flex-1")}>
      <div className={cn("pointer-events-none absolute inset-x-0 -bottom-6 z-10 flex h-[var(--notification-window-height,calc(75dvh+1.5rem))] [overflow-x:var(--notification-overflow,hidden)] [overflow-y:var(--notification-overflow,auto)] overscroll-contain pb-6 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden",
        position === "bottom" ? "flex-col-reverse" : "flex-col")}>
        <ol ref={list} id={listId} aria-label="Notification list" onFocusCapture={() => setReadingCards(true)}
          onPointerEnter={event => { if (event.pointerType !== "touch") setHover(true); }}
          onPointerLeave={() => setHover(false)}
          onBlurCapture={event => { if (left(event)) setReadingCards(false); }}
          className={cn("pointer-events-auto relative isolate shrink-0", position === "top" && "mt-auto")} style={{ height: layout.height + 8 }}>
          <AnimatePresence initial={false}>
            {shown.map((item, index) => <NotificationCard key={item.id} item={item} offset={layout.offsets.get(item.id)!}
              layer={position === "top" ? shown.length - index : index + 1} position={position}
              depth={expanded ? 0 : position === "top" ? index : shown.length - 1 - index}
              motion={motion} className={cardClassName} dismiss={() => dismissCard(item.id, index)} />)}
          </AnimatePresence>
        </ol>
      </div>
    </div>
    {items.length > 1 && <button type="button" aria-controls={listId} aria-expanded={showAll}
      onClick={() => setShowAll(value => !value)}
      className="mx-auto mt-2 flex h-8 min-w-28 shrink-0 items-center justify-center gap-1 rounded-md px-2 text-xs font-medium text-muted-foreground hover:bg-muted focus-visible:bg-muted">
      {showAll ? <>Show less <ChevronUp aria-hidden="true" className="size-3.5" /></> :
        <>Show all {items.length} <ChevronDown aria-hidden="true" className="size-3.5" /></>}
    </button>}
  </section>;
}

"use client";

import { useEffect, useRef } from "react";

/** Keep a clock for each queued item, including ones outside the compact view. */
export function NotificationTimer({ id, duration, paused, onDismiss }: {
  id: string; duration: number; paused: boolean; onDismiss: (id: string) => void;
}) {
  const remaining = useRef(duration);
  const dismiss = useRef(onDismiss);
  useEffect(() => { dismiss.current = onDismiss; }, [onDismiss]);
  useEffect(() => { remaining.current = duration; }, [duration]);
  useEffect(() => {
    if (paused || !Number.isFinite(duration) || duration <= 0) return;
    const start = Date.now();
    const timer = setTimeout(() => dismiss.current(id), remaining.current);
    return () => {
      clearTimeout(timer);
      remaining.current = Math.max(0, remaining.current - (Date.now() - start));
    };
  }, [id, duration, paused]);
  return null;
}
